use ratatui::{
    Frame,
    layout::Rect,
    style::{Modifier, Style},
    text::{Line, Span},
    widgets::{Paragraph, Wrap},
};

use crate::{
    app::{DiffScope, DiffViewerState},
    theme::Theme,
};

/// Header count when some of the files are AMF's own: `5 files · 1 is yours ·
/// 4 generated by AMF`. Spelled out per number so a singular never reads as
/// `1 yours` or `1 files`.
pub(super) fn amf_split_count_label(yours: usize, amf: usize) -> String {
    let total = yours + amf;
    let files = if total == 1 { "file" } else { "files" };
    let yours = match yours {
        0 => "none are yours".to_string(),
        1 => "1 is yours".to_string(),
        n => format!("{n} are yours"),
    };
    format!("{total} {files} · {yours} · {amf} generated by AMF")
}

pub(super) fn draw_header(frame: &mut Frame, area: Rect, state: &DiffViewerState, theme: &Theme) {
    let branch = if state.branch.is_empty() {
        "(unknown branch)"
    } else {
        &state.branch
    };
    let no_base_fallback = state.no_base_branch && matches!(state.scope, DiffScope::CurrentChanges);
    let base = if no_base_fallback {
        crate::diff::NO_BASE_BRANCH_LABEL
    } else if state.base_ref.is_empty() {
        "(no base)"
    } else {
        &state.base_ref
    };
    let commit = if state.base_commit.is_empty() || no_base_fallback {
        String::new()
    } else {
        let short = state.base_commit.chars().take(12).collect::<String>();
        format!(" @ {short}")
    };
    // With AMF's own files in the diff, the count says how many are the
    // reviewer's and the totals cover only those, so `+107` of injected hook
    // settings can't make a one-line edit look like a large change.
    let yours = &state.files[..state.amf_files_start()];
    let additions: usize = yours.iter().map(|file| file.additions).sum();
    let deletions: usize = yours.iter().map(|file| file.deletions).sum();
    let count_label = if state.amf_file_count > 0 {
        format!(
            " {}  ",
            amf_split_count_label(yours.len(), state.amf_file_count)
        )
    } else {
        format!(" {} file(s)  ", state.files.len())
    };

    let mut second_line = vec![
        Span::styled(count_label, Style::default().fg(theme.text.to_color())),
        Span::styled(
            format!("+{additions}"),
            Style::default()
                .fg(theme.success.to_color())
                .add_modifier(Modifier::BOLD),
        ),
        Span::raw("  "),
        Span::styled(
            format!("-{deletions}"),
            Style::default()
                .fg(theme.danger.to_color())
                .add_modifier(Modifier::BOLD),
        ),
    ];

    if state.review {
        let (approved, rejected) = review_counts(state);
        let pending = state.files.len().saturating_sub(approved + rejected);
        second_line.push(Span::raw("   "));
        second_line.push(Span::styled(
            format!("✓ {approved}"),
            Style::default()
                .fg(theme.success.to_color())
                .add_modifier(Modifier::BOLD),
        ));
        second_line.push(Span::raw("  "));
        second_line.push(Span::styled(
            format!("✗ {rejected}"),
            Style::default()
                .fg(theme.danger.to_color())
                .add_modifier(Modifier::BOLD),
        ));
        second_line.push(Span::raw("  "));
        second_line.push(Span::styled(
            format!("· {pending}"),
            Style::default().fg(theme.text_muted.to_color()),
        ));
        // On a re-review, show how many files changed since the last round.
        if state.has_prior_review {
            second_line.push(Span::raw("   "));
            second_line.push(Span::styled(
                format!("Δ {} changed", state.changed_since_last.len()),
                Style::default()
                    .fg(theme.warning.to_color())
                    .add_modifier(Modifier::BOLD),
            ));
        }
    } else {
        second_line.push(Span::raw("  "));
        second_line.push(Span::styled(
            state.workdir.to_string_lossy().into_owned(),
            Style::default().fg(theme.text_muted.to_color()),
        ));
    }

    let scope_line = match &state.scope {
        DiffScope::CurrentChanges => vec![
            Span::styled(" Branch ", Style::default().fg(theme.text_muted.to_color())),
            Span::styled(
                branch.to_string(),
                Style::default()
                    .fg(theme.project_title.to_color())
                    .add_modifier(Modifier::BOLD),
            ),
            Span::styled("  vs  ", Style::default().fg(theme.text_muted.to_color())),
            Span::styled(
                format!("{base}{commit}"),
                Style::default()
                    .fg(theme.primary.to_color())
                    .add_modifier(Modifier::BOLD),
            ),
            if state.override_base_ref.is_some() {
                Span::styled("  (manual)", Style::default().fg(theme.warning.to_color()))
            } else {
                Span::raw("")
            },
        ],
        DiffScope::PullRequest(target) => pr_scope_line(target, theme),
        DiffScope::Commit(commit) => vec![
            Span::styled(" Commit ", Style::default().fg(theme.text_muted.to_color())),
            Span::styled(
                commit.short_hash.clone(),
                Style::default()
                    .fg(theme.primary.to_color())
                    .add_modifier(Modifier::BOLD),
            ),
            Span::raw("  "),
            Span::styled(
                commit.subject.clone(),
                Style::default()
                    .fg(theme.project_title.to_color())
                    .add_modifier(Modifier::BOLD),
            ),
        ],
    };
    let header = Paragraph::new(vec![Line::from(scope_line), Line::from(second_line)])
        .wrap(Wrap { trim: false });

    frame.render_widget(header, area);
}

/// `PR #N · @author · base…head` with short OIDs: which PR, whose, and exactly
/// which revisions the review is pinned to.
fn pr_scope_line(target: &crate::app::PrDiffTarget, theme: &Theme) -> Vec<Span<'static>> {
    let short = |oid: &str| oid.get(..7).unwrap_or(oid).to_string();
    let muted = Style::default().fg(theme.text_muted.to_color());
    let strong =
        |color: ratatui::style::Color| Style::default().fg(color).add_modifier(Modifier::BOLD);
    vec![
        Span::styled(
            format!(" PR #{}", target.pr.number),
            strong(theme.primary.to_color()),
        ),
        Span::styled(format!(" · @{}", target.pr.author), muted),
        Span::styled(" · ", muted),
        Span::styled(
            format!("{} {}", target.pr.base_ref, short(&target.merge_base_oid)),
            strong(theme.project_title.to_color()),
        ),
        Span::styled("…", muted),
        Span::styled(
            format!(
                "{} {}",
                target.pr.branch_label(),
                short(&target.pr.head_oid)
            ),
            strong(theme.project_title.to_color()),
        ),
        Span::styled(format!("  {}", target.pr.title), muted),
    ]
}

/// Count approved and rejected files in a review-mode viewer.
fn review_counts(state: &DiffViewerState) -> (usize, usize) {
    let mut approved = 0;
    let mut rejected = 0;
    for file in &state.files {
        match state.decisions.get(&file.path) {
            Some(crate::app::ReviewDecision::Approve) => approved += 1,
            Some(crate::app::ReviewDecision::Reject { .. }) => rejected += 1,
            None => {}
        }
    }
    (approved, rejected)
}
